-- mistri store layout: mail, sqlite, version 1. Generated by scripts/store-layouts.mjs; never edit by hand.
CREATE TABLE "__mistri_mail_meta" (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  version INTEGER NOT NULL CHECK (version = 1)
);
CREATE TABLE "__mistri_mail_log" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  at INTEGER NOT NULL,
  tenant_id TEXT,
  recipient TEXT NOT NULL,
  sender TEXT,
  message_id TEXT,
  outcome TEXT NOT NULL CHECK (outcome IN ('applied','replayed','refused','dropped','unrouted')),
  reason TEXT
);
CREATE INDEX "__mistri_mail_log_at" ON "__mistri_mail_log" (at);
CREATE TABLE "__mistri_mail_link" (
  nonce TEXT PRIMARY KEY NOT NULL,
  tenant_id TEXT NOT NULL,
  resource TEXT NOT NULL,
  key_json TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL,
  revoked_at INTEGER
);
CREATE INDEX "__mistri_mail_link_record" ON "__mistri_mail_link" (tenant_id, resource, key_json);
CREATE INDEX "__mistri_mail_link_expires" ON "__mistri_mail_link" (expires_at);
